import test from'node:test';import assert from'node:assert/strict';import{make,validate,apply}from'./state.js';import{history,transition,undo,portable,parse}from'../creative-kit/state.js';const config={make,validate,apply};
test('branching records ancestry without turning a question into an answer',()=>{const w=make();apply(w,{type:'branch',id:'q5',parent:'q1',relation:'invert'});assert.equal(w.items[4].parent,'q1');assert.equal(w.items[4].status,'open');assert.equal(w.items[4].answer,'');assert.throws(()=>apply(w,{type:'remove',id:'q1'}));});
test('changing lens preserves writing and selected questions; undo restores a removed leaf',()=>{const w=make();w.items[0].ideas='A reversible envelope';apply(w,{type:'move',id:'q1',kind:'design'});assert.equal(w.items[0].ideas,'A reversible envelope');assert.ok(w.selected.includes('q1'));let h=history({version:1,activeId:w.id,workspaces:[w]});h=transition(h,{type:'remove',id:'q1'},config);assert.ok(!h.present.workspaces[0].selected.includes('q1'));assert.deepEqual(undo(h).present.workspaces[0],w);});
test('imports preserve unresolved questions and reject missing selections',()=>{const w=make();assert.deepEqual(parse(portable(w,'questions',validate),'questions',validate),w);w.selected.push('missing');assert.throws(()=>validate(w));});
